package sirius.db.jdbc.schema

import org.junit.jupiter.api.Test
import org.junit.jupiter.api.extension.ExtendWith
import sirius.db.jdbc.TestEntity
import sirius.db.mixing.Mixing
import sirius.kernel.SiriusExtension
import sirius.kernel.di.std.Part
import java.sql.Types
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import kotlin.test.assertNull

/**
 * Pins the DDL statements generated by the [MySQLDatabaseDialect] and the rules it applies when comparing columns.
 *
 * The statements are executed against production schemas by the [SchemaTool], therefore the expected strings are
 * spelled out verbatim, including the whitespace left behind by empty optional parts.
 */
@ExtendWith(SiriusExtension::class)
class MySQLDatabaseDialectTest {

    @Test
    fun `create table lists columns, keys and the primary key`() {
        val table = Table(mixing.getDescriptor(TestEntity::class.java))
        table.name = "person"
        table.columns.add(column("id", Types.BIGINT, nullable = false, autoIncrement = true))
        table.columns.add(column("name", Types.VARCHAR, length = 50, nullable = true, defaultValue = "x"))
        table.keys.add(key("idx_name", unique = false, "name"))
        table.keys.add(key("uq_name", unique = true, "name"))
        table.primaryKey.add("id")

        assertEquals(
            "CREATE TABLE `person` (\n" +
                    "  `id` BIGINT(20) NOT NULL AUTO_INCREMENT ,\n" +
                    "  `name` VARCHAR(50)   DEFAULT 'x',\n" +
                    "   KEY `idx_name` (name),\n" +
                    "   CONSTRAINT `uq_name` UNIQUE (name),\n" +
                    " PRIMARY KEY (id)\n" +
                    ") ENGINE=InnoDB",
            dialect.generateCreateTable(table)
        )
    }

    @Test
    fun `add column renders type, nullability, auto increment and default`() {
        assertEquals(
            "ALTER TABLE `person` ADD COLUMN `name` VARCHAR(50) NOT NULL  DEFAULT 'x'",
            dialect.generateAddColumn(table("person"), column("name", Types.VARCHAR, length = 50, defaultValue = "x"))
        )
        assertEquals(
            "ALTER TABLE `person` ADD COLUMN `id` BIGINT(20) NOT NULL AUTO_INCREMENT ",
            dialect.generateAddColumn(table("person"), column("id", Types.BIGINT, autoIncrement = true))
        )
        assertEquals(
            "ALTER TABLE `person` ADD COLUMN `age` INTEGER   ",
            dialect.generateAddColumn(table("person"), column("age", Types.INTEGER, nullable = true))
        )
    }

    @Test
    fun `numeric defaults are not quoted while text and date defaults are`() {
        assertEquals(
            "ALTER TABLE `t` ADD COLUMN `amount` DECIMAL(10,2) NOT NULL  DEFAULT 0",
            dialect.generateAddColumn(
                table("t"),
                column("amount", Types.DECIMAL, precision = 10, scale = 2, defaultValue = "0")
            )
        )
        assertEquals(
            "ALTER TABLE `t` ADD COLUMN `flag` TINYINT NOT NULL  DEFAULT 1",
            dialect.generateAddColumn(table("t"), column("flag", Types.TINYINT, defaultValue = "1"))
        )
        assertEquals(
            "ALTER TABLE `t` ADD COLUMN `day` DATE NOT NULL  DEFAULT '2020-01-01'",
            dialect.generateAddColumn(table("t"), column("day", Types.DATE, defaultValue = "2020-01-01"))
        )
    }

    @Test
    fun `char columns become varchar and missing lengths default to 255`() {
        assertEquals(
            "ALTER TABLE `t` ADD COLUMN `code` VARCHAR(10) NOT NULL  ",
            dialect.generateAddColumn(table("t"), column("code", Types.CHAR, length = 10))
        )
        assertEquals(
            "ALTER TABLE `t` ADD COLUMN `code` VARCHAR(255) NOT NULL  ",
            dialect.generateAddColumn(table("t"), column("code", Types.CHAR))
        )
        assertEquals(
            "ALTER TABLE `t` ADD COLUMN `code` VARCHAR(255) NOT NULL  ",
            dialect.generateAddColumn(table("t"), column("code", Types.VARCHAR))
        )
    }

    @Test
    fun `alter column renames when an old name is given`() {
        assertEquals(
            listOf("ALTER TABLE `t` CHANGE COLUMN `old` `new` INTEGER NOT NULL  "),
            dialect.generateAlterColumnTo(table("t"), "old", column("new", Types.INTEGER))
        )
        assertEquals(
            listOf("ALTER TABLE `t` CHANGE COLUMN `same` `same` INTEGER NOT NULL  "),
            dialect.generateAlterColumnTo(table("t"), null, column("same", Types.INTEGER))
        )
    }

    @Test
    fun `table level statements are rendered as expected`() {
        val renamed = table("people")
        renamed.oldName = "person"
        val withPrimaryKey = table("t")
        withPrimaryKey.primaryKey.add("a")
        withPrimaryKey.primaryKey.add("b")

        assertEquals("DROP TABLE `t` ", dialect.generateDropTable(table("t")))
        assertEquals("ALTER TABLE `person` RENAME `people`", dialect.generateRenameTable(renamed))
        assertEquals(
            listOf("ALTER TABLE `t` DROP PRIMARY KEY, ADD PRIMARY KEY (a, b)"),
            dialect.generateAlterPrimaryKey(withPrimaryKey)
        )
        assertEquals(
            "ALTER TABLE `t` DROP COLUMN `c`",
            dialect.generateDropColumn(table("t"), column("c", Types.INTEGER))
        )
    }

    @Test
    fun `keys are added as index or unique constraint and altered by drop and add`() {
        val index = key("idx_ab", unique = false, "a", "b")
        val unique = key("uq_a", unique = true, "a")

        assertEquals("ALTER TABLE `t` ADD INDEX `idx_ab` (a, b)", dialect.generateAddKey(table("t"), index))
        assertEquals("ALTER TABLE `t` ADD CONSTRAINT `uq_a` UNIQUE (a)", dialect.generateAddKey(table("t"), unique))
        assertEquals("ALTER TABLE `t` DROP INDEX `idx_ab`", dialect.generateDropKey(table("t"), index))
        assertEquals(
            listOf("ALTER TABLE `t` DROP INDEX `idx_ab`", "ALTER TABLE `t` ADD CONSTRAINT `uq_a` UNIQUE (a)"),
            dialect.generateAlterKey(table("t"), index, unique)
        )
        assertEquals(
            listOf("ALTER TABLE `t` ADD CONSTRAINT `uq_a` UNIQUE (a)"),
            dialect.generateAlterKey(table("t"), null, unique)
        )
    }

    @Test
    fun `foreign keys are added, dropped and altered`() {
        val foreignKey = foreignKey("fk_t_user", "user", "user_id" to "id")

        assertEquals(
            "ALTER TABLE `t` ADD CONSTRAINT `fk_t_user` FOREIGN KEY (user_id) REFERENCES `user` (id)",
            dialect.generateAddForeignKey(table("t"), foreignKey)
        )
        assertEquals(
            "ALTER TABLE `t` DROP FOREIGN KEY `fk_t_user`",
            dialect.generateDropForeignKey(table("t"), foreignKey)
        )
        assertEquals(
            listOf(
                "ALTER TABLE `t` DROP FOREIGN KEY `fk_t_user`",
                "ALTER TABLE `t` ADD CONSTRAINT `fk_t_user` FOREIGN KEY (user_id) REFERENCES `user` (id)"
            ),
            dialect.generateAlterForeignKey(table("t"), foreignKey, foreignKey)
        )
    }

    @Test
    fun `foreign key names are cut to the 64 characters MySQL allows`() {
        val longName = "fk_" + "x".repeat(70)
        val foreignKey = foreignKey(longName, "user", "user_id" to "id")

        assertEquals(
            "ALTER TABLE `t` DROP FOREIGN KEY `${longName.take(64)}`",
            dialect.generateDropForeignKey(table("t"), foreignKey)
        )
        assertEquals(
            "ALTER TABLE `t` ADD CONSTRAINT `${longName.take(64)}` FOREIGN KEY (user_id) REFERENCES `user` (id)",
            dialect.generateAddForeignKey(table("t"), foreignKey)
        )
    }

    @Test
    fun `columns of equal settings are reported as equal`() {
        assertNull(dialect.areColumnsEqual(column("c", Types.INTEGER), column("c", Types.INTEGER)))
        assertNull(
            dialect.areColumnsEqual(
                column("c", Types.VARCHAR, length = 50),
                column("c", Types.CHAR, length = 50)
            )
        )
        assertNull(dialect.areColumnsEqual(column("c", Types.BOOLEAN), column("c", Types.BIT)))
        assertNull(dialect.areColumnsEqual(column("c", Types.LONGVARCHAR), column("c", Types.CLOB)))
        assertNull(dialect.areColumnsEqual(column("c", Types.BLOB), column("c", Types.LONGVARBINARY)))
        assertNull(
            dialect.areColumnsEqual(
                column("c", Types.NUMERIC, precision = 10, scale = 2),
                column("c", Types.DECIMAL, precision = 10, scale = 2)
            )
        )
    }

    @Test
    fun `differing types, lengths, precisions and scales are reported`() {
        assertNotNull(dialect.areColumnsEqual(column("c", Types.INTEGER), column("c", Types.BIGINT)))
        assertNotNull(
            dialect.areColumnsEqual(
                column("c", Types.VARCHAR, length = 50),
                column("c", Types.VARCHAR, length = 100)
            )
        )
        assertNotNull(
            dialect.areColumnsEqual(
                column("c", Types.DECIMAL, precision = 10, scale = 2),
                column("c", Types.DECIMAL, precision = 12, scale = 2)
            )
        )
        assertNotNull(
            dialect.areColumnsEqual(
                column("c", Types.DECIMAL, precision = 10, scale = 2),
                column("c", Types.DECIMAL, precision = 10, scale = 3)
            )
        )
    }

    @Test
    fun `a target without length accepts any length`() {
        assertNull(dialect.areColumnsEqual(column("c", Types.VARCHAR), column("c", Types.VARCHAR, length = 100)))
    }

    @Test
    fun `nullability differences are reported except for timestamps without default`() {
        assertNotNull(
            dialect.areColumnsEqual(
                column("c", Types.INTEGER, nullable = true),
                column("c", Types.INTEGER, nullable = false)
            )
        )
        assertNull(
            dialect.areColumnsEqual(
                column("c", Types.TIMESTAMP, nullable = true),
                column("c", Types.TIMESTAMP, nullable = false)
            )
        )
    }

    @Test
    fun `equivalent spellings of default values are treated as equal`() {
        assertNull(
            dialect.areColumnsEqual(
                column("c", Types.DOUBLE, defaultValue = "0"),
                column("c", Types.DOUBLE, defaultValue = "0.0")
            )
        )
        assertNull(
            dialect.areColumnsEqual(
                column("c", Types.DECIMAL, precision = 10, scale = 3, defaultValue = "1"),
                column("c", Types.DECIMAL, precision = 10, scale = 3, defaultValue = "1.000")
            )
        )
        assertNull(
            dialect.areColumnsEqual(
                column("c", Types.VARCHAR, length = 5, defaultValue = "x"),
                column("c", Types.VARCHAR, length = 5, defaultValue = "'x'")
            )
        )
        assertNull(
            dialect.areColumnsEqual(
                column("c", Types.VARCHAR, length = 5),
                column("c", Types.VARCHAR, length = 5, defaultValue = "''")
            )
        )
        assertNotNull(
            dialect.areColumnsEqual(
                column("c", Types.INTEGER, defaultValue = "1"),
                column("c", Types.INTEGER, defaultValue = "2")
            )
        )
    }

    @Test
    fun `completing table infos quotes text defaults and removes the primary index`() {
        val table = table("t")
        table.columns.add(column("text", Types.VARCHAR, length = 5, defaultValue = "x"))
        table.columns.add(column("quoted", Types.VARCHAR, length = 5, defaultValue = "'y'"))
        table.columns.add(column("number", Types.INTEGER, defaultValue = "1"))
        table.keys.add(key("PRIMARY", unique = true, "id"))
        table.keys.add(key("idx_text", unique = false, "text"))

        dialect.completeTableInfos(table)

        assertEquals(listOf("'x'", "'y'", "1"), table.columns.map { it.defaultValue })
        assertEquals(listOf("idx_text"), table.keys.map { it.name })
    }

    private fun table(name: String) = Table().apply { this.name = name }

    @Suppress("LongParameterList")
    private fun column(
        name: String,
        type: Int,
        length: Int = 0,
        precision: Int = 0,
        scale: Int = 0,
        nullable: Boolean = false,
        autoIncrement: Boolean = false,
        defaultValue: String? = null
    ) = TableColumn().apply {
        this.name = name
        this.type = type
        this.length = length
        this.precision = precision
        this.scale = scale
        this.isNullable = nullable
        this.isAutoIncrement = autoIncrement
        this.defaultValue = defaultValue
    }

    private fun key(name: String, unique: Boolean, vararg columns: String) = Key().apply {
        this.name = name
        this.isUnique = unique
        columns.forEachIndexed { index, column -> addColumn(index + 1, column) }
    }

    private fun foreignKey(name: String, foreignTable: String, vararg columns: Pair<String, String>) =
        ForeignKey().apply {
            this.name = name
            this.foreignTable = foreignTable
            columns.forEachIndexed { index, (column, foreignColumn) ->
                addColumn(index + 1, column)
                addForeignColumn(index + 1, foreignColumn)
            }
        }

    companion object {
        private val dialect = MySQLDatabaseDialect()

        @Part
        private lateinit var mixing: Mixing
    }
}
